from pathlib import Path

root=Path('modern')

# version and JaCoCo core-coverage policy
p=root/'pom.xml'
s=p.read_text()
s=s.replace('<version>1.0.16</version>','<version>1.0.17</version>',1)
old='''<configuration><rules><rule><element>BUNDLE</element><limits><limit><counter>LINE</counter><value>COVEREDRATIO</value><minimum>0.80</minimum></limit></limits></rule></rules></configuration>'''
new='''<configuration>\n              <rules>\n                <rule>\n                  <element>BUNDLE</element>\n                  <includes>\n                    <include>com.revature.project0.domain.*</include>\n                    <include>com.revature.project0.app.*</include>\n                    <include>com.revature.project0.resilience.*</include>\n                    <include>com.revature.project0.cache.*</include>\n                  </includes>\n                  <excludes>\n                    <exclude>com.revature.project0.app.error.*</exclude>\n                  </excludes>\n                  <limits>\n                    <limit>\n                      <counter>LINE</counter>\n                      <value>COVEREDRATIO</value>\n                      <minimum>0.80</minimum>\n                    </limit>\n                  </limits>\n                </rule>\n              </rules>\n            </configuration>'''
if old not in s: raise SystemExit('expected JaCoCo rule not found')
p.write_text(s.replace(old,new))

files={
'src/test/java/com/revature/project0/app/ApplicationEdgeCaseTest.java': 'package com.revature.project0.app;\n\nimport com.revature.project0.adapter.*;\nimport com.revature.project0.domain.*;\nimport java.math.BigDecimal;\nimport java.util.UUID;\nimport org.junit.jupiter.api.Test;\nimport static org.junit.jupiter.api.Assertions.*;\n\nclass ApplicationEdgeCaseTest {\n    @Test void inventoryRejectsUnknownAndSoldRemoval() {\n        var repo = new InMemoryVehicleRepository();\n        var service = new InventoryService(repo);\n        assertThrows(IllegalArgumentException.class, () -> service.removeVehicle(UUID.randomUUID()));\n        var sold = repo.save(Vehicle.create("Honda","Civic",2020));\n        sold.markSold();\n        repo.save(sold);\n        assertThrows(IllegalStateException.class, () -> service.removeVehicle(sold.getId()));\n    }\n\n    @Test void userAdministrationCreatesRolesAndRejectsDuplicates() {\n        var repo = new InMemoryUserRepository();\n        PasswordHasher hasher = new PasswordHasher() {\n            public String hash(String raw) { return "h:" + raw; }\n            public boolean matches(String raw, String stored) { return stored.equals("h:" + raw); }\n        };\n        var service = new UserAdministrationService(repo, hasher);\n        var employee = service.createUser("emp", "secret", Role.EMPLOYEE);\n        assertEquals(Role.EMPLOYEE, employee.getRole());\n        assertNotEquals("secret", employee.getPasswordHash());\n        assertThrows(IllegalArgumentException.class,\n                () -> service.createUser("emp", "again", Role.CUSTOMER));\n    }\n\n    @Test void offerServiceRejectsMissingOrUnavailableTargetsAndCanRejectOffer() {\n        var vehicles = new InMemoryVehicleRepository();\n        var offers = new InMemoryOfferRepository();\n        var purchases = new InMemoryPurchaseRepository();\n        var service = new OfferService(offers, vehicles, purchases);\n        UUID customer = UUID.randomUUID();\n        assertThrows(IllegalArgumentException.class,\n                () -> service.makeOffer(customer, UUID.randomUUID(), BigDecimal.TEN));\n\n        var vehicle = vehicles.save(Vehicle.create("Toyota","Corolla",2020));\n        vehicle.markSold();\n        vehicles.save(vehicle);\n        assertThrows(IllegalStateException.class,\n                () -> service.makeOffer(customer, vehicle.getId(), BigDecimal.TEN));\n\n        var available = vehicles.save(Vehicle.create("Mazda","3",2021));\n        var offer = service.makeOffer(customer, available.getId(), new BigDecimal("15000"));\n        UUID employee = UUID.randomUUID();\n        service.rejectOffer(employee, offer.getId());\n        assertEquals(OfferStatus.REJECTED, offers.findById(offer.getId()).orElseThrow().getStatus());\n        assertTrue(service.listCustomerOffers(customer).stream().anyMatch(o -> o.getId().equals(offer.getId())));\n        assertTrue(service.listPendingOffers().isEmpty());\n    }\n}\n',
'src/test/java/com/revature/project0/cache/CachePolicyTest.java': 'package com.revature.project0.cache;\n\nimport java.time.Duration;\nimport org.junit.jupiter.api.Test;\nimport static org.junit.jupiter.api.Assertions.*;\n\nclass CachePolicyTest {\n    @Test void validatesAndExposesPolicy() {\n        var p = new CachePolicy("vehicles", Duration.ofMinutes(5), 100);\n        assertEquals("vehicles", p.name());\n        assertEquals(100, p.maxEntries());\n        assertThrows(IllegalArgumentException.class, () -> new CachePolicy(" ", Duration.ofMinutes(1), 1));\n        assertThrows(IllegalArgumentException.class, () -> new CachePolicy("x", Duration.ZERO, 1));\n        assertThrows(IllegalArgumentException.class, () -> new CachePolicy("x", Duration.ofSeconds(1), 0));\n    }\n}\n',
'src/test/java/com/revature/project0/domain/DomainInvariantTest.java': 'package com.revature.project0.domain;\n\nimport java.math.BigDecimal;\nimport java.util.UUID;\nimport org.junit.jupiter.api.Test;\nimport static org.junit.jupiter.api.Assertions.*;\n\nclass DomainInvariantTest {\n    @Test void userAndVehicleFactoriesEnforceStateAndTransitions() {\n        var user = User.create("dane", "hash", Role.CUSTOMER);\n        assertEquals("dane", user.getUsername());\n        assertEquals(Role.CUSTOMER, user.getRole());\n        assertThrows(IllegalArgumentException.class, () -> User.create(" ", "hash", Role.CUSTOMER));\n\n        var vehicle = Vehicle.create("Honda", "Civic", 2020);\n        long v0 = vehicle.getVersion();\n        assertTrue(vehicle.isAvailable());\n        vehicle.markSold();\n        assertFalse(vehicle.isAvailable());\n        assertEquals(v0 + 1, vehicle.getVersion());\n        vehicle.markSold();\n        assertEquals(v0 + 1, vehicle.getVersion());\n        vehicle.markAvailable();\n        assertTrue(vehicle.isAvailable());\n        assertEquals(v0 + 2, vehicle.getVersion());\n        assertThrows(IllegalArgumentException.class, () -> Vehicle.create("", "Civic", 2020));\n    }\n\n    @Test void offerTransitionsAreOneWayAndValidated() {\n        UUID customer = UUID.randomUUID();\n        UUID vehicle = UUID.randomUUID();\n        UUID employee = UUID.randomUUID();\n        var offer = Offer.create(customer, vehicle, new BigDecimal("12000"));\n        assertEquals(OfferStatus.PENDING, offer.getStatus());\n        assertThrows(IllegalArgumentException.class,\n                () -> Offer.create(customer, vehicle, BigDecimal.ZERO));\n        offer.accept(employee);\n        assertEquals(OfferStatus.ACCEPTED, offer.getStatus());\n        assertEquals(employee, offer.getDecidedByEmployeeId());\n        assertThrows(IllegalStateException.class, () -> offer.reject(employee));\n    }\n\n    @Test void purchaseAndPaymentScheduleValidateRequiredValues() {\n        var schedule = PaymentSchedule.of(new BigDecimal("10000"), 4);\n        var purchase = Purchase.create(UUID.randomUUID(), UUID.randomUUID(), UUID.randomUUID(), schedule);\n        assertEquals(new BigDecimal("2500.00"), purchase.getSchedule().getMonthlyPayment());\n        assertThrows(IllegalArgumentException.class,\n                () -> PaymentSchedule.of(BigDecimal.ZERO, 12));\n    }\n}\n',
'src/test/java/com/revature/project0/resilience/ResiliencePrimitiveTest.java': 'package com.revature.project0.resilience;\n\nimport java.time.Duration;\nimport java.util.concurrent.atomic.AtomicInteger;\nimport java.util.concurrent.atomic.AtomicLong;\nimport org.junit.jupiter.api.Test;\nimport static org.junit.jupiter.api.Assertions.*;\n\nclass ResiliencePrimitiveTest {\n    @Test void retrySucceedsAfterTransientFailuresAndStopsOnNonRetryable() {\n        var sleeps = new AtomicInteger();\n        var attempts = new AtomicInteger();\n        var executor = new RetryExecutor(\n                new RetryPolicy(3, Duration.ofMillis(1), Duration.ofMillis(4)),\n                d -> sleeps.incrementAndGet());\n        String result = executor.execute(() -> {\n            if (attempts.incrementAndGet() < 3) throw new IllegalStateException("transient");\n            return "ok";\n        }, t -> true);\n        assertEquals("ok", result);\n        assertEquals(3, attempts.get());\n        assertEquals(2, sleeps.get());\n\n        var once = new AtomicInteger();\n        assertThrows(IllegalArgumentException.class,\n                () -> executor.execute(() -> {\n                    once.incrementAndGet();\n                    throw new IllegalArgumentException("fatal");\n                }, t -> false));\n        assertEquals(1, once.get());\n    }\n\n    @Test void retryPoliciesValidateInputsAndInterruptedSleepIsSurfaced() {\n        assertThrows(IllegalArgumentException.class,\n                () -> new RetryPolicy(0, Duration.ofMillis(1), Duration.ofMillis(1)));\n        assertThrows(IllegalArgumentException.class,\n                () -> new RetryPolicy(1, Duration.ZERO, Duration.ofMillis(1)));\n        assertThrows(IllegalArgumentException.class,\n                () -> new RetryPolicy(1, Duration.ofMillis(2), Duration.ofMillis(1)));\n\n        var executor = new RetryExecutor(\n                new RetryPolicy(2, Duration.ofMillis(1), Duration.ofMillis(1)),\n                d -> { throw new InterruptedException("stop"); });\n        assertThrows(IllegalStateException.class,\n                () -> executor.execute(() -> { throw new IllegalStateException("retry"); }, t -> true));\n        assertTrue(Thread.interrupted());\n    }\n\n    @Test void circuitOpensAndSuccessfulHalfOpenProbeClosesIt() {\n        var clock = new AtomicLong();\n        var breaker = new SimpleCircuitBreaker(\n                new CircuitBreakerPolicy(2, 50.0, Duration.ofNanos(10)),\n                clock::get);\n        assertEquals("ok", breaker.execute(() -> "ok"));\n        assertThrows(IllegalStateException.class,\n                () -> breaker.execute(() -> { throw new IllegalStateException("boom"); }));\n        assertEquals(SimpleCircuitBreaker.State.OPEN, breaker.state());\n        assertThrows(SimpleCircuitBreaker.CircuitOpenException.class,\n                () -> breaker.execute(() -> "blocked"));\n\n        clock.set(10);\n        assertEquals(SimpleCircuitBreaker.State.HALF_OPEN, breaker.state());\n        assertEquals("recovered", breaker.execute(() -> "recovered"));\n        assertEquals(SimpleCircuitBreaker.State.CLOSED, breaker.state());\n    }\n\n    @Test void circuitPolicyValidatesInputs() {\n        assertThrows(IllegalArgumentException.class,\n                () -> new CircuitBreakerPolicy(0, 50, Duration.ofSeconds(1)));\n        assertThrows(IllegalArgumentException.class,\n                () -> new CircuitBreakerPolicy(1, 0, Duration.ofSeconds(1)));\n        assertThrows(IllegalArgumentException.class,\n                () -> new CircuitBreakerPolicy(1, 101, Duration.ofSeconds(1)));\n        assertThrows(IllegalArgumentException.class,\n                () -> new CircuitBreakerPolicy(1, 50, Duration.ZERO));\n    }\n}\n',
}
for rel,content in files.items():
    p=root/rel
    p.parent.mkdir(parents=True,exist_ok=True)
    p.write_text(content)

